from pathlib import Path
import csv,html,json
OUT=Path(__file__).resolve().parent
m=json.loads((OUT/'manifest.json').read_text());r=json.loads((OUT/'runs.json').read_text());audit=json.loads((OUT/'audit.json').read_text());assert audit['passed'] and len(r)==16
r.sort(key=lambda x:x['weighted_score']);base=next(x for x in r if x['variant']=='current_lex');cur=next(x for x in r if x['variant']=='current_weighted');best=r[0]
fields=['variant','label','objective','seed','late_count','on_time_rate','total_lateness_min','distance_km','weighted_score','end_to_end_seconds','iterations']
with (OUT/'comparison.csv').open('w',newline='',encoding='utf-8-sig') as f:
 w=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');w.writeheader();w.writerows(r)
summary=f"单种子结果：加权总分最低的是{best['label']}（{best['weighted_score']:.6f}）。当前算法改用加权后，逾期任务 {base['late_count']}→{cur['late_count']}，总逾期 {base['total_lateness_min']:.2f}→{cur['total_lateness_min']:.2f} 分钟，航程 {base['distance_km']:.2f}→{cur['distance_km']:.2f} 公里。"
rows=''.join(f"<tr><td>{1+sum(y["weighted_score"]<x["weighted_score"] for y in r)}</td><td>{html.escape(x['label'])}</td><td>{'原词典序' if x['objective']=='lexicographic' else '加权'}</td><td>{x['late_count']}</td><td>{x['on_time_rate']:.1%}</td><td>{x['total_lateness_min']:.2f}</td><td>{x['distance_km']:.2f}</td><td>{x['weighted_score']:.6f}</td><td>{x['end_to_end_seconds']:.2f}</td><td>{x['iterations']}</td></tr>" for i,x in enumerate(r,1))
plots=[]
for field,title,fmt in [('weighted_score','加权总分 · 越低越好','.6f'),('late_count','逾期任务数 · 个','.0f'),('total_lateness_min','总逾期 · 分钟','.2f'),('distance_km','航程 · 公里','.2f')]:
 maxval=max(x[field] for x in r);bars=''.join(f'<div class="barrow"><span>{html.escape(x["label"])}</span><div class="track"><div class="fill {"control" if x["variant"]=="current_lex" else "current" if x["variant"]=="current_weighted" else ""}" style="width:{x[field]/maxval*100:.3f}%"></div></div><b>{format(x[field],fmt)}</b></div>' for x in r)
 plots.append(f'<section><h2>{title}</h2><div class="axis"><span>0</span><span>{maxval:.2f}</span></div>{bars}</section>')
notes=''.join('<li>'+html.escape(x)+'</li>' for x in m['scope_notes'])
data=json.dumps([dict(label=x['label'],variant=x['variant'],construction=x['construction_seconds'],trajectory=x['best_trajectory']) for x in r],ensure_ascii=False).replace('</','<\\/')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>纯直送：240 秒加权目标对比</title><style>
:root{color-scheme:light dark;--bg:light-dark(#f7f8fa,#15181c);--fg:light-dark(#17212b,#e6ebef);--muted:light-dark(#55616e,#aeb8c1);--line:light-dark(#d8e0e6,#3b4249);--series:light-dark(#387da1,#67b0d5);--control:light-dark(#79746b,#c1b5a1);--current:light-dark(#267e59,#66bd95)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:15px/1.65 system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:32px 24px}h1{font-size:30px;margin-bottom:8px}h2{font-size:18px;font-weight:600}p{max-width:1100px}.meta{color:var(--muted)}.plots{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:30px 40px;margin:32px 0}.barrow{display:grid;grid-template-columns:160px minmax(40px,1fr) 90px;gap:10px;align-items:center;min-height:32px;font-size:13px}.barrow b{font-weight:500;text-align:right;font-variant-numeric:tabular-nums}.track{height:14px;background:color-mix(in srgb,var(--line) 45%,transparent)}.fill{height:14px;background:var(--series)}.control{background:var(--control)}.current{background:var(--current)}.axis{display:flex;justify-content:space-between;margin:0 100px 5px 170px;color:var(--muted);font-size:12px}.tablewrap{overflow-x:auto}table{border-collapse:collapse;width:100%;white-space:nowrap;font-size:14px}th,td{padding:10px 12px;border-bottom:1px solid var(--line);text-align:right;font-variant-numeric:tabular-nums}th:nth-child(2),td:nth-child(2){text-align:left}a{color:var(--series)}code{overflow-wrap:anywhere}select{font:inherit;padding:5px 10px;max-width:100%}svg{display:block;width:100%;height:300px;color:var(--fg)}@media(max-width:850px){.plots{grid-template-columns:1fr}main{padding:20px 12px}h1{font-size:25px}.barrow{grid-template-columns:135px minmax(30px,1fr) 78px;font-size:12px;gap:6px}.axis{margin-left:141px;margin-right:84px}}</style><main>
<h1>纯直送：240 秒加权目标对比</h1><p class="meta">200 个任务 · 8 架无人机 · 原点起飞 · 同一种子 __SEED__ · 16 次正式运行 · 全部独立核验通过</p>
<p>__SUMMARY__</p><p>这是一轮单种子探索，排名只描述这次运行；没有修改默认算法，也没有据此认定某个方法稳定更好。</p>
<p><strong>固定评分：</strong>J = 0.50 × 逾期数 / 200 + 0.25 × 总逾期分钟 / __L__ + 0.25 × 航程 / __D__，越低越好。分母来自共同初解，结果出来后没有调整。权重为本轮探索设定，并非题目官方评分。</p>
<p class="meta">以下四图按同一加权排名排列，横条均从零开始，各图使用自己的物理单位。灰色为当前原词典序对照，绿色为当前加权版本，蓝色为其他历史方法的加权适配版本。</p><div class="plots">__PLOTS__</div>
<h2>完整结果</h2><div class="tablewrap"><table><thead><tr><th>排名</th><th>方法</th><th>搜索目标</th><th>逾期数</th><th>按时率</th><th>总逾期/min</th><th>航程/km</th><th>加权 J</th><th>实际秒数</th><th>迭代数</th></tr></thead><tbody>__ROWS__</tbody></table></div>
<h2>加权总分随时间变化</h2><label for="method">查看方法：</label><select id="method"></select><svg id="curve" role="img" aria-label="所选方法的历史最优解，统一按加权总分展示"></svg><p class="meta">横轴包含构造时间。原词典序对照的加权分数允许上升，因为它优化的是另一种目标；加权版本的历史最优分数应单调不增。</p>
<h2>实验边界与核验</h2><ul>__NOTES__<li>时间从读取 CSV 开始，到完整核验、解文件写出结束；每次预留 1 秒收尾，所以实际时间约 239 秒。各版本顺序运行，没有并行争抢求解资源。</li><li>独立逐访问复算欧氏距离与飞行时间，检查 200 项任务完整性、取送先后、容量 2、每机最多 25 项任务和无中继；三项原始指标、加权总分均与求解结果一致。</li><li>加权比较包含目标适配的计算开销和搜索轨迹变化，单次运行无法将它们分离。当前原目标完成 21374 次迭代，加权版完成 11269 次；较少迭代仍取得更低加权分，但不能据此概括运行效率。</li><li>历史序列化器中 problem.objective_order 保留项目原字段；本轮实际搜索目标以 runs.json 的 objective 及 manifest.json 的权重公式为准。</li></ul>
<p><a href="comparison.csv">下载比较 CSV</a> · <a href="runs.json">原始结果</a> · <a href="manifest.json">冻结协议与源码</a> · <a href="audit.json">独立核验</a></p></main><script>
const records=__DATA__,scaleL=__L__,scaleD=__D__,sel=document.getElementById('method'),svg=document.getElementById('curve');
records.forEach(r=>{let o=document.createElement('option');o.value=r.variant;o.textContent=r.label;sel.append(o)});sel.value='current_weighted';
function draw(){let r=records.find(r=>r.variant===sel.value),w=svg.clientWidth,h=300,left=65,right=18,top=20,bottom=45;svg.setAttribute('viewBox',`0 0 ${w} ${h}`);let pts=r.trajectory.map(t=>[t[1]+r.construction,.5*t[2]/200+.25*t[3]/scaleL+.25*t[4]/scaleD]);let ymin=Math.min(...pts.map(p=>p[1]))-.015,ymax=Math.max(...pts.map(p=>p[1]))+.015;let X=t=>left+t/240*(w-left-right),Y=v=>top+(ymax-v)/(ymax-ymin)*(h-top-bottom);let out=`<rect x="${left}" y="${top}" width="${w-left-right}" height="${h-top-bottom}" fill="none" stroke="var(--line)"/>`;
for(let i=0;i<=4;i++){let t=i*60,x=X(t);out+=`<text x="${x}" y="${h-bottom+20}" fill="currentColor" font-size="12" text-anchor="${i===4?'end':'middle'}">${t}</text>`;let v=ymin+i/4*(ymax-ymin);out+=`<text x="${left-8}" y="${Y(v)+4}" fill="currentColor" font-size="12" text-anchor="end">${v.toFixed(3)}</text>`}out+=`<text x="${left}" y="13" fill="currentColor" font-size="12">加权 J</text><text x="${w-right}" y="${h-4}" fill="currentColor" font-size="12" text-anchor="end">端到端时间 / 秒</text>`;
let path=pts.map((p,i)=>(i?'H'+X(p[0])+'V':'M'+X(p[0])+',')+Y(p[1])).join(' ');out+=`<path d="${path}" fill="none" stroke="var(--series)" stroke-width="2"/>`;svg.innerHTML=out}
sel.addEventListener('change',draw);new ResizeObserver(draw).observe(svg);draw();</script></html>'''
for key,val in {'SEED':str(m['seed']),'SUMMARY':html.escape(summary),'L':str(m['scales'][1]),'D':str(m['scales'][2]),'PLOTS':''.join(plots),'ROWS':rows,'NOTES':notes,'DATA':data}.items():page=page.replace('__'+key+'__',val)
(OUT/'index.html').write_text(page)
(OUT/'README.md').write_text('# 240 秒纯直送加权试验\n\n'+summary+'\n\n'+m['protocol']+'\n\n'+'\n'.join('- '+n for n in m['scope_notes'])+'\n\n原始解中 objective_order 为历史序列化字段；实际目标以 manifest 与 runs.json 为准。\n\n复算：`python algorithm/results/weighted_direct_240s_20261014/audit.py`\n\n重建报告：`python algorithm/results/weighted_direct_240s_20261014/report.py`\n')
print(summary)
